contracts/core/MondaloreVParimutuelMarke.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable2Step.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/Address.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "../token/MondaloreOutcomeToken.sol";
import "../interfaces/IMondaloreAggregatorV3.sol";
import "../interfaces/IMondaloreFeeReceiver.sol";
import "../interfaces/IMondaloreMarketFactoryResolution.sol";

interface IDRPDebtRepay {
    function usdead() external view returns (address);
    function repayDebt(address user, address token, uint256 amountDebtToBurn) external;
}

/// @title MondaloreVParimutuelMarket
/// @notice vPari: virtual + real pricing; native ETH (collateral address(0)) or ERC20; multi-outcome PRICE via bins.
contract MondaloreVParimutuelMarket is Ownable2Step, ReentrancyGuard {
    using SafeERC20 for IERC20;

    uint256 public constant BPS_DENOMINATOR = 10_000;
    /// @notice Total fee taken from each trade (1.5%).
    uint256 public constant TRADE_FEE_TOTAL_BPS = 150;
    /// @notice Of the 1.5% trade fee, 0.3% goes to the market creator.
    uint256 public constant CREATOR_FEE_BPS = 30;
    /// @notice Remaining 1.2% goes to the protocol fee recipient.
    uint256 public constant PROTOCOL_FEE_BPS = 120;
    bytes32 private constant EVENT_RESOLUTION_TYPEHASH =
        keccak256("EventResolution(address market,uint8 outcomeIndex,uint256 chainId)");
    bytes32 private constant EIP712_DOMAIN_TYPEHASH =
        keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)");
    bytes32 private constant EIP712_NAME_HASH = keccak256("Mondalore Market");
    bytes32 private constant EIP712_VERSION_HASH = keccak256("1");

    /// @notice Minimum deposit to ensure fees are non-zero (> 10_000 / 30 = 334 wei).
    uint256 public constant MIN_DEPOSIT = 1000;

    enum MarketKind {
        PRICE,
        EVENT
    }

    enum PriceThresholdKind {
        ABOVE,
        BELOW,
        IN_RANGE
    }

    enum MarketState {
        OPEN,
        _LEGACY_AWAITING_UMA_SLOT,
        SETTLED
    }

    address public immutable factory;
    address public immutable feeRecipient;
    /// @notice The address that created this market via the factory; receives CREATOR_FEE_BPS of each trade.
    address public immutable creator;
    /// @notice address(0) = native ETH (wei). Otherwise ERC20 collateral.
    address public immutable collateralAddress;
    uint8 public immutable collateralDecimals;
    uint8 public immutable numOutcomes;
    uint256 public immutable virtualReserve;
    uint256 public immutable stakeEndTimestamp;
    uint256 public immutable resolveAfterTimestamp;
    MarketKind public immutable marketKind;
    bytes32 public immutable metadataHash;

    address public immutable chainlinkFeed;
    uint256 public immutable priceThreshold;
    PriceThresholdKind public immutable priceThresholdKind;
    uint256 public immutable priceUpperBound;
    uint256 public immutable maxPriceStaleness;

    /// @notice Minimum total collateral for the one-time permissionless `bootstrapLiquidity` (split evenly across outcomes).
    uint256 public immutable minBootstrapTotal;

    MondaloreOutcomeToken[] private _outcomeTokens;
    uint256[] public realPool;
    /// @notice If length == numOutcomes, PRICE settles by bin; else binary threshold mode (numOutcomes==2).
    uint256[] public priceBinLower;
    uint256[] public priceBinUpper;

    bool public initialized;
    MarketState public state;
    /// @notice Off-chain metadata location for the UI (e.g. `ipfs://bafy...` or gateway URL).
    string public metadataURI;

    uint256 public winningOutcomeIndex;
    uint256 public redemptionRate;
    int256 public settledOraclePrice;
    uint256 public settlementTimestamp;

    address public bootstrapFunder;
    bool public bootstrapped;

    /// @notice Collateral claimable by feeRecipient when a market settles with zero winning shares.
    /// @dev Pull pattern — avoids DoS if feeRecipient is a reverting contract.
    uint256 public unclaimedResidue;

    /// @notice Whitelisted DRP contract addresses for redeemAndRepayDebt.
    mapping(address => bool) public isApprovedDrp;

    uint256 private constant WIN_UNSET = type(uint256).max;

    event MarketInitialized(address[] outcomeTokens, string metadataURI);
    event Deposited(
        address indexed buyer,
        address indexed recipient,
        uint8 indexed outcomeIndex,
        uint256 collateralAmount,
        uint256 sharesMinted,
        uint256 price1e18,
        uint256 timestamp
    );
    event MarketSettled(uint256 winningOutcomeIndex, uint256 distributableToWinners);
    event ResidueAccrued(uint256 amount);
    event ResidueClaimed(address indexed to, uint256 amount);
    event DrpApproved(address indexed drp);
    event DrpRevoked(address indexed drp);
    event TokensRedeemed(address indexed user, uint8 indexed outcomeIndex, uint256 shares, uint256 payout);
    event TokensRedeemedAndDebtRepayAttempted(
        address indexed user,
        uint8 indexed outcomeIndex,
        uint256 shares,
        uint256 payout,
        address indexed drp,
        address vaultCollateralToken,
        uint256 debtRequestedToBurn
    );
    event EventResolved(uint8 indexed outcomeIndex, address indexed caller, uint256 adminSignatures);
    event LiquidityBootstrapped(
        address indexed funder,
        address indexed shareRecipient,
        uint256 totalAmount,
        uint256 perOutcome
    );

    error OnlyFactory();
    error AlreadyInitialized();
    error NotInitialized();
    error InvalidOutcome();
    error StakePeriodEnded();
    error TooEarlyToResolve();
    error MarketNotOpen();
    error InvalidState();
    error ZeroShares();
    error Slippage();
    error NoRedemption();
    error EthAmount();
    error UnexpectedEth();
    error AlreadyBootstrapped();
    error BelowMinBootstrap();
    error NotDivisibleBootstrap();
    error InvalidShareRecipient();
    error InvalidResolutionSignatures();
    error InvalidDrp();
    error InvalidDebtRepayToken();
    error InvalidDrpAddress();
    error BelowMinDeposit();

    modifier onlyFactory() {
        if (msg.sender != factory) revert OnlyFactory();
        _;
    }

    constructor(
        address factory_,
        address owner_,
        address feeRecipient_,
        address creator_,
        address collateralAddress_,
        uint8 collateralDecimals_,
        uint8 numOutcomes_,
        uint256 virtualReserve_,
        uint256 stakeEndTimestamp_,
        uint256 resolveAfterTimestamp_,
        MarketKind kind_,
        bytes32 metadataHash_,
        address chainlinkFeed_,
        uint256 priceThreshold_,
        PriceThresholdKind priceKind_,
        uint256 priceUpperBound_,
        uint256 maxPriceStaleness_,
        uint256 minBootstrapTotal_
    ) Ownable(owner_) {
        require(factory_ != address(0) && owner_ != address(0) && feeRecipient_ != address(0), "Zero address");
        require(creator_ != address(0), "Zero creator");
        require(numOutcomes_ >= 2 && numOutcomes_ <= 32, "Outcomes range");
        require(virtualReserve_ > 0, "Virtual reserve");
        require(stakeEndTimestamp_ > block.timestamp, "Stake end past");
        require(resolveAfterTimestamp_ > stakeEndTimestamp_, "Resolve order");
        require(metadataHash_ != bytes32(0), "Metadata");
        if (collateralAddress_ == address(0)) {
            require(collateralDecimals_ == 18, "ETH 18 dec");
        }

        factory = factory_;
        feeRecipient = feeRecipient_;
        creator = creator_;
        collateralAddress = collateralAddress_;
        collateralDecimals = collateralDecimals_;
        numOutcomes = numOutcomes_;
        virtualReserve = virtualReserve_;
        stakeEndTimestamp = stakeEndTimestamp_;
        resolveAfterTimestamp = resolveAfterTimestamp_;
        marketKind = kind_;
        metadataHash = metadataHash_;

        if (kind_ == MarketKind.PRICE) {
            require(chainlinkFeed_ != address(0), "Feed");
            require(maxPriceStaleness_ > 0, "Staleness");
            if (priceKind_ == PriceThresholdKind.IN_RANGE) {
                require(priceThreshold_ < priceUpperBound_, "Range bounds");
            }
            chainlinkFeed = chainlinkFeed_;
            priceThreshold = priceThreshold_;
            priceThresholdKind = priceKind_;
            priceUpperBound = priceUpperBound_;
            maxPriceStaleness = maxPriceStaleness_;
        } else {
            chainlinkFeed = address(0);
            priceThreshold = 0;
            priceThresholdKind = PriceThresholdKind.ABOVE;
            priceUpperBound = 0;
            maxPriceStaleness = 0;
        }

        minBootstrapTotal = minBootstrapTotal_;
        winningOutcomeIndex = WIN_UNSET;
    }

    function initialize(
        address[] calldata outcomeTokenAddresses,
        uint256[] calldata binLower,
        uint256[] calldata binUpper,
        string calldata metadataURI_
    ) external onlyFactory {
        if (initialized) revert AlreadyInitialized();
        require(outcomeTokenAddresses.length == uint256(numOutcomes), "Token count");
        initialized = true;

        for (uint256 i = 0; i < outcomeTokenAddresses.length; i++) {
            _outcomeTokens.push(MondaloreOutcomeToken(outcomeTokenAddresses[i]));
            realPool.push(0);
        }

        if (marketKind == MarketKind.PRICE) {
            if (binLower.length > 0) {
                require(binLower.length == uint256(numOutcomes) && binUpper.length == uint256(numOutcomes), "Bins");
                for (uint256 i = 0; i < binLower.length; i++) {
                    require(binLower[i] <= binUpper[i], "Bin bounds");
                    priceBinLower.push(binLower[i]);
                    priceBinUpper.push(binUpper[i]);
                }
            } else {
                require(uint256(numOutcomes) == 2, "Bins or N=2");
            }
        }

        metadataURI = metadataURI_;

        emit MarketInitialized(outcomeTokenAddresses, metadataURI_);
    }

    function outcomeToken(uint256 index) external view returns (address) {
        return address(_outcomeTokens[index]);
    }

    /// @notice Owner approves a DRP contract for use in redeemAndRepayDebt.
    /// @dev Fix #5: whitelist valid DRP addresses instead of accepting any user-supplied address.
    function approveDrp(address drp) external onlyOwner {
        require(drp != address(0), "Zero drp");
        isApprovedDrp[drp] = true;
        emit DrpApproved(drp);
    }

    function revokeDrp(address drp) external onlyOwner {
        isApprovedDrp[drp] = false;
        emit DrpRevoked(drp);
    }

    /// @notice Claim residue collateral that accrued when a market settled with zero winning shares.
    /// @dev Fix #4: pull pattern — feeRecipient calls this instead of receiving a push during settlement.
    function claimResidue() external nonReentrant {
        uint256 amount = unclaimedResidue;
        require(amount > 0, "No residue");
        unclaimedResidue = 0;
        _sendCollateral(feeRecipient, amount);
        emit ResidueClaimed(feeRecipient, amount);
    }

    /// @notice Fix #7: After all winners have redeemed, sweep any rounding dust to feeRecipient.
    /// @dev Double floor-division in redemptionRate * shares / 1e18 leaves up to (winSupply-1)/1e18
    ///      wei permanently locked. Owner can sweep this after the market is fully settled.
    function sweepDust() external onlyOwner nonReentrant {
        require(state == MarketState.SETTLED, "Not settled");
        uint256 winIdx = winningOutcomeIndex;
        require(winIdx != WIN_UNSET, "Not settled");
        // Any remaining balance beyond what's owed to outstanding shares is dust.
        uint256 outstanding = (_outcomeTokens[winIdx].totalSupply() * redemptionRate) / 1e18;
        uint256 bal;
        if (collateralAddress == address(0)) {
            bal = address(this).balance;
        } else {
            bal = IERC20(collateralAddress).balanceOf(address(this));
        }
        // Subtract unclaimed residue so we don't double-count.
        uint256 available = bal > unclaimedResidue ? bal - unclaimedResidue : 0;
        uint256 dust = available > outstanding ? available - outstanding : 0;
        if (dust > 0) {
            _sendCollateral(feeRecipient, dust);
            emit ResidueClaimed(feeRecipient, dust);
        }
    }

    function priceOf(uint8 outcomeIndex) public view returns (uint256) {
        if (!initialized) revert NotInitialized();
        if (outcomeIndex >= numOutcomes) revert InvalidOutcome();
        uint256 totalWeight;
        for (uint256 j = 0; j < uint256(numOutcomes); j++) {
            totalWeight += virtualReserve + realPool[j];
        }
        require(totalWeight > 0, "Weight");
        return ((virtualReserve + realPool[outcomeIndex]) * 1e18) / totalWeight;
    }

    receive() external payable {}

    function deposit(uint8 outcomeIndex, uint256 amount, address recipient, uint256 minSharesOut) external payable nonReentrant {
        if (!initialized) revert NotInitialized();
        if (state != MarketState.OPEN) revert MarketNotOpen();
        if (block.timestamp >= stakeEndTimestamp) revert StakePeriodEnded();
        if (outcomeIndex >= numOutcomes) revert InvalidOutcome();
        require(amount > 0, "Amount");
        // Fix #6: enforce minimum deposit so fee calculations never truncate to zero.
        require(amount >= MIN_DEPOSIT, "Below min deposit");
        require(recipient != address(0), "Recipient");

        if (collateralAddress == address(0)) {
            if (msg.value != amount) revert EthAmount();
        } else {
            require(msg.value == 0, "No ETH");
            IERC20(collateralAddress).safeTransferFrom(msg.sender, address(this), amount);
        }

        // Deduct 1.5% trade fee: 0.3% to creator, 1.2% to protocol fee recipient.
        uint256 creatorFee = (amount * CREATOR_FEE_BPS) / BPS_DENOMINATOR;
        uint256 protocolFee = (amount * PROTOCOL_FEE_BPS) / BPS_DENOMINATOR;
        uint256 netAmount = amount - creatorFee - protocolFee;

        if (creatorFee > 0) _sendCollateral(creator, creatorFee);
        if (protocolFee > 0) _sendProtocolFee(protocolFee);

        uint256 p = priceOf(outcomeIndex);
        require(p > 0, "Price");
        uint256 shares = (netAmount * 1e18) / p;
        if (shares == 0) revert ZeroShares();
        if (shares < minSharesOut) revert Slippage();

        realPool[outcomeIndex] += netAmount;
        _outcomeTokens[outcomeIndex].mint(recipient, shares);

        emit Deposited(msg.sender, recipient, outcomeIndex, amount, shares, p, block.timestamp);
    }

    /// @notice One-time permissionless seed: split `totalAmount` evenly across all outcomes, mint shares to `shareRecipient`.
    /// @dev Bootstrap liquidity is exempt from trade fees to ensure fair seeding.
    function bootstrapLiquidity(uint256 totalAmount, address shareRecipient) external payable nonReentrant {
        if (!initialized) revert NotInitialized();
        if (state != MarketState.OPEN) revert MarketNotOpen();
        if (block.timestamp >= stakeEndTimestamp) revert StakePeriodEnded();
        if (bootstrapped) revert AlreadyBootstrapped();
        if (shareRecipient == address(0)) revert InvalidShareRecipient();
        if (totalAmount == 0 || totalAmount < minBootstrapTotal) revert BelowMinBootstrap();

        uint256 n = uint256(numOutcomes);
        if (totalAmount % n != 0) revert NotDivisibleBootstrap();
        uint256 per = totalAmount / n;

        if (collateralAddress == address(0)) {
            if (msg.value != totalAmount) revert EthAmount();
        } else {
            if (msg.value != 0) revert UnexpectedEth();
            IERC20(collateralAddress).safeTransferFrom(msg.sender, address(this), totalAmount);
        }

        // Fix #1: Snapshot all prices BEFORE any pool update so every outcome
        // gets shares computed at the same pre-bootstrap price, preventing
        // later outcomes from receiving more shares due to growing totalWeight.
        uint256[] memory prices = new uint256[](uint256(numOutcomes));
        for (uint8 i = 0; i < numOutcomes; i++) {
            prices[i] = priceOf(i);
            require(prices[i] > 0, "Price");
        }

        for (uint8 i = 0; i < numOutcomes; i++) {
            uint256 shares = (per * 1e18) / prices[i];
            if (shares == 0) revert ZeroShares();
            realPool[i] += per;
            _outcomeTokens[i].mint(shareRecipient, shares);
            emit Deposited(msg.sender, shareRecipient, i, per, shares, prices[i], block.timestamp);
        }
        bootstrapFunder = msg.sender;
        bootstrapped = true;
        emit LiquidityBootstrapped(msg.sender, shareRecipient, totalAmount, per);
    }

    function settlePrice() external nonReentrant {
        if (!initialized) revert NotInitialized();
        if (marketKind != MarketKind.PRICE) revert InvalidState();
        if (state != MarketState.OPEN) revert InvalidState();
        if (block.timestamp < resolveAfterTimestamp) revert TooEarlyToResolve();

        (uint80 roundId, int256 answer, , uint256 updatedAt, uint80 answeredInRound) = IMondaloreAggregatorV3(chainlinkFeed).latestRoundData();
        require(answer > 0, "Answer");
        require(block.timestamp - updatedAt <= maxPriceStaleness, "Stale");
        // Fix #3: guard against a completed round that carries a stale answer from a prior round.
        require(answeredInRound >= roundId, "Stale round");

        uint8 dec = IMondaloreAggregatorV3(chainlinkFeed).decimals();
        uint256 normalized;
        if (dec >= 6) {
            normalized = uint256(answer) / (10 ** (dec - 6));
        } else {
            normalized = uint256(answer) * (10 ** (6 - dec));
        }

        uint256 winIdx = _winningOutcomePrice(normalized);
        _finalizeSettlement(winIdx, answer);
    }

    /// @notice Settle an EVENT market using EIP-712 signatures from factory `resolutionAdmins` (3-of-10).
    /// @dev Each signature commits to `(this market, outcomeIndex, chainId)` — not reusable across markets/outcomes.
    function resolveEvent(
        uint8 outcomeIndex,
        address[] calldata signers,
        bytes[] calldata signatures
    ) external nonReentrant {
        if (!initialized) revert NotInitialized();
        if (marketKind != MarketKind.EVENT) revert InvalidState();
        if (state != MarketState.OPEN) revert InvalidState();
        if (block.timestamp < resolveAfterTimestamp) revert TooEarlyToResolve();
        if (outcomeIndex >= numOutcomes) revert InvalidOutcome();
        if (signers.length != signatures.length || signers.length == 0) revert InvalidResolutionSignatures();

        IMondaloreMarketFactoryResolution fac = IMondaloreMarketFactoryResolution(factory);
        uint256 threshold = fac.resolutionThreshold();
        if (signers.length < threshold) revert InvalidResolutionSignatures();

        bytes32 digest = _eventResolutionDigest(outcomeIndex);
        uint256 valid;
        for (uint256 i = 0; i < signers.length; i++) {
            address signer = signers[i];
            if (!fac.isResolutionAdmin(signer)) revert InvalidResolutionSignatures();
            if (_recoverSigner(digest, signatures[i]) != signer) revert InvalidResolutionSignatures();
            for (uint256 j = 0; j < i; j++) {
                if (signers[j] == signer) revert InvalidResolutionSignatures();
            }
            valid++;
        }
        if (valid < threshold) revert InvalidResolutionSignatures();

        _finalizeSettlement(outcomeIndex, int256(uint256(outcomeIndex)));
        emit EventResolved(outcomeIndex, msg.sender, valid);
    }

    function redeem(uint8 outcomeIndex, uint256 shareAmount) external nonReentrant {
        if (!initialized) revert NotInitialized();
        if (state != MarketState.SETTLED) revert InvalidState();
        if (shareAmount == 0) revert ZeroShares();
        if (outcomeIndex >= numOutcomes) revert InvalidOutcome();
        if (outcomeIndex != uint8(winningOutcomeIndex)) revert InvalidOutcome();
        if (redemptionRate == 0) revert NoRedemption();

        uint256 payout = (shareAmount * redemptionRate) / 1e18;
        require(payout > 0, "Payout");

        _outcomeTokens[outcomeIndex].burnFrom(msg.sender, shareAmount);
        _sendCollateral(msg.sender, payout);

        emit TokensRedeemed(msg.sender, outcomeIndex, shareAmount, payout);
    }

    /// @notice Redeem winning shares, then attempt DRP debt repayment in the same tx.
    /// @dev Requires market collateral to be USDeAD and DRP manager permissions configured for this market.
    function redeemAndRepayDebt(
        uint8 outcomeIndex,
        uint256 shareAmount,
        address drp,
        address vaultCollateralToken,
        uint256 debtToBurn
    ) external nonReentrant {
        if (!initialized) revert NotInitialized();
        if (state != MarketState.SETTLED) revert InvalidState();
        if (shareAmount == 0) revert ZeroShares();
        if (outcomeIndex >= numOutcomes) revert InvalidOutcome();
        if (outcomeIndex != uint8(winningOutcomeIndex)) revert InvalidOutcome();
        if (redemptionRate == 0) revert NoRedemption();
        if (drp == address(0)) revert InvalidDrp();
        // Fix #5: only allow whitelisted DRP addresses — prevents malicious user-supplied drp.
        if (!isApprovedDrp[drp]) revert InvalidDrpAddress();

        if (collateralAddress == address(0) || collateralAddress != IDRPDebtRepay(drp).usdead()) {
            revert InvalidDebtRepayToken();
        }

        uint256 payout = (shareAmount * redemptionRate) / 1e18;
        require(payout > 0, "Payout");

        _outcomeTokens[outcomeIndex].burnFrom(msg.sender, shareAmount);
        _sendCollateral(msg.sender, payout);

        IDRPDebtRepay(drp).repayDebt(msg.sender, vaultCollateralToken, debtToBurn);

        emit TokensRedeemed(msg.sender, outcomeIndex, shareAmount, payout);
        emit TokensRedeemedAndDebtRepayAttempted(
            msg.sender,
            outcomeIndex,
            shareAmount,
            payout,
            drp,
            vaultCollateralToken,
            debtToBurn
        );
    }

    function _sendCollateral(address to, uint256 amount) private {
        if (collateralAddress == address(0)) {
            Address.sendValue(payable(to), amount);
        } else {
            IERC20(collateralAddress).safeTransfer(to, amount);
        }
    }

    /// @dev Send protocol fees to feeRecipient. If feeRecipient implements IMondaloreFeeReceiver,
    ///      call receiveFees() so the vault accumulator updates atomically.
    ///      Falls back to a plain transfer for non-vault recipients.
    function _sendProtocolFee(uint256 amount) private {
        if (amount == 0) return;
        // Check if feeRecipient implements the vault hook (low-level staticcall to avoid revert on EOA).
        bool isVault = _supportsReceiveFees(feeRecipient);
        if (isVault) {
            if (collateralAddress == address(0)) {
                IMondaloreFeeReceiver(feeRecipient).receiveFees{value: amount}(address(0), amount);
            } else {
                IERC20(collateralAddress).forceApprove(feeRecipient, amount);
                IMondaloreFeeReceiver(feeRecipient).receiveFees(collateralAddress, amount);
            }
        } else {
            _sendCollateral(feeRecipient, amount);
        }
    }

    /// @dev Returns true if `target` has code and responds to the IMondaloreFeeReceiver selector.
    function _supportsReceiveFees(address target) private view returns (bool) {
        if (target.code.length == 0) return false;
        // ERC165-style check: call supportsInterface(IMondaloreFeeReceiver.receiveFees.selector)
        // We use a simpler approach: check for a known 4-byte selector via staticcall.
        (bool ok, bytes memory ret) = target.staticcall(
            abi.encodeWithSignature("supportsInterface(bytes4)", type(IMondaloreFeeReceiver).interfaceId)
        );
        return ok && ret.length == 32 && abi.decode(ret, (bool));
    }

    function _winningOutcomePrice(uint256 normalizedPrice) internal view returns (uint256) {
        if (priceBinLower.length == uint256(numOutcomes)) {
            uint256 matches;
            uint256 win;
            for (uint256 i = 0; i < uint256(numOutcomes); i++) {
                if (normalizedPrice >= priceBinLower[i] && normalizedPrice <= priceBinUpper[i]) {
                    matches++;
                    win = i;
                }
            }
            require(matches == 1, "One bin");
            return win;
        }
        require(uint256(numOutcomes) == 2, "Bins");
        bool firstWins;
        if (priceThresholdKind == PriceThresholdKind.ABOVE) {
            firstWins = normalizedPrice >= priceThreshold;
        } else if (priceThresholdKind == PriceThresholdKind.BELOW) {
            firstWins = normalizedPrice <= priceThreshold;
        } else {
            firstWins = normalizedPrice >= priceThreshold && normalizedPrice <= priceUpperBound;
        }
        return firstWins ? 0 : 1;
    }

    function _domainSeparator() internal view returns (bytes32) {
        return keccak256(
            abi.encode(
                EIP712_DOMAIN_TYPEHASH,
                EIP712_NAME_HASH,
                EIP712_VERSION_HASH,
                block.chainid,
                address(this)
            )
        );
    }

    function _eventResolutionDigest(uint8 outcomeIndex) internal view returns (bytes32) {
        bytes32 structHash = keccak256(
            abi.encode(EVENT_RESOLUTION_TYPEHASH, address(this), outcomeIndex, block.chainid)
        );
        return keccak256(abi.encodePacked("\x19\x01", _domainSeparator(), structHash));
    }

    function _recoverSigner(bytes32 digest, bytes calldata signature) internal pure returns (address) {
        if (signature.length != 65) revert InvalidResolutionSignatures();
        bytes32 r;
        bytes32 s;
        uint8 v;
        assembly {
            r := calldataload(signature.offset)
            s := calldataload(add(signature.offset, 32))
            v := byte(0, calldataload(add(signature.offset, 64)))
        }
        if (v < 27) {
            v += 27;
        }
        if (v != 27 && v != 28) revert InvalidResolutionSignatures();
        return ecrecover(digest, v, r, s);
    }

    function _finalizeSettlement(uint256 winIdx, int256 oraclePrice) internal {
        uint256 winSupply = _outcomeTokens[winIdx].totalSupply();
        uint256 winReal = realPool[winIdx];

        // All loser pool collateral goes directly to winners (fees were already collected per-trade).
        uint256 distributable = 0;
        for (uint256 j = 0; j < uint256(numOutcomes); j++) {
            if (j != winIdx) {
                distributable += realPool[j];
            }
        }

        if (winSupply > 0) {
            redemptionRate = ((winReal + distributable) * 1e18) / winSupply;
        } else {
            // Fix #4: Use pull pattern instead of push to avoid DoS if feeRecipient reverts.
            // Residue is stored and claimable by feeRecipient via claimResidue().
            redemptionRate = 0;
            uint256 residue = winReal + distributable;
            if (residue > 0) {
                unclaimedResidue += residue;
                emit ResidueAccrued(residue);
            }
        }

        winningOutcomeIndex = winIdx;
        settledOraclePrice = oraclePrice;
        settlementTimestamp = block.timestamp;
        state = MarketState.SETTLED;

        emit MarketSettled(winIdx, distributable);
    }
}

contracts/factory/MondaloreParimutuelBat.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable2Step.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "./MondaloreParimutuelMarketFactory.sol";

/// @title MondaloreParimutuelBatchFactory
/// @notice Batch helper that calls the core Mondalore factory repeatedly for multi-collateral deployments.
/// @dev Only supports ERC20 collateral markets (not native ETH) due to per-market bootstrap amounts.
///      Caller must pre-approve this contract for sum(bootstrapAmount) across all collateral tokens.
contract MondaloreParimutuelBatchFactory is Ownable2Step {
    using SafeERC20 for IERC20;

    MondaloreParimutuelMarketFactory public immutable coreFactory;

    constructor(address owner_, address coreFactory_) Ownable(owner_) {
        require(coreFactory_ != address(0), "Factory");
        coreFactory = MondaloreParimutuelMarketFactory(coreFactory_);
    }

    /// @notice Deploy multiple price markets, one per collateral token.
    /// @dev Caller must pre-approve this contract for `templateParams.bootstrapAmount` per collateral token.
    ///      All markets share the same bootstrapAmount and shareRecipient from the template.
    function createPriceMarketsBatch(
        MondaloreParimutuelMarketFactory.PriceMarketParams calldata templateParams,
        address[] calldata collateralTokens
    ) external onlyOwner returns (address[] memory deployed) {
        require(templateParams.collateralToken == address(0) || true, ""); // silence unused warning
        deployed = new address[](collateralTokens.length);
        for (uint256 i = 0; i < collateralTokens.length; i++) {
            address token = collateralTokens[i];
            require(token != address(0), "ETH not supported in batch");

            MondaloreParimutuelMarketFactory.PriceMarketParams memory p = _copyPrice(templateParams);
            p.collateralToken = token;
            p.collateralDecimals = templateParams.collateralDecimals;

            // Pull bootstrap collateral from caller and approve factory.
            IERC20(token).safeTransferFrom(msg.sender, address(this), p.bootstrapAmount);
            IERC20(token).forceApprove(address(coreFactory), p.bootstrapAmount);

            deployed[i] = coreFactory.createPriceMarket(p);
        }
    }

    /// @notice Deploy multiple event markets, one per collateral token.
    /// @dev Caller must pre-approve this contract for `templateParams.bootstrapAmount` per collateral token.
    function createEventMarketsBatch(
        MondaloreParimutuelMarketFactory.EventMarketParams calldata templateParams,
        address[] calldata collateralTokens
    ) external onlyOwner returns (address[] memory deployed) {
        deployed = new address[](collateralTokens.length);
        for (uint256 i = 0; i < collateralTokens.length; i++) {
            address token = collateralTokens[i];
            require(token != address(0), "ETH not supported in batch");

            MondaloreParimutuelMarketFactory.EventMarketParams memory p = _copyEvent(templateParams);
            p.collateralToken = token;
            p.collateralDecimals = templateParams.collateralDecimals;

            // Pull bootstrap collateral from caller and approve factory.
            IERC20(token).safeTransferFrom(msg.sender, address(this), p.bootstrapAmount);
            IERC20(token).forceApprove(address(coreFactory), p.bootstrapAmount);

            deployed[i] = coreFactory.createEventMarket(p);
        }
    }

    function _copyPrice(MondaloreParimutuelMarketFactory.PriceMarketParams calldata p)
        internal
        pure
        returns (MondaloreParimutuelMarketFactory.PriceMarketParams memory q)
    {
        q.collateralToken = p.collateralToken;
        q.collateralDecimals = p.collateralDecimals;
        q.virtualReserve = p.virtualReserve;
        q.stakeEndTimestamp = p.stakeEndTimestamp;
        q.resolveAfterTimestamp = p.resolveAfterTimestamp;
        q.metadataHash = p.metadataHash;
        q.outcomeLabels = p.outcomeLabels;
        q.metadataURI = p.metadataURI;
        q.priceAssetKey = p.priceAssetKey;
        q.priceThreshold = p.priceThreshold;
        q.priceKind = p.priceKind;
        q.priceUpperBound = p.priceUpperBound;
        q.maxPriceStaleness = p.maxPriceStaleness;
        q.priceBinLower = p.priceBinLower;
        q.priceBinUpper = p.priceBinUpper;
        q.minBootstrapTotal = p.minBootstrapTotal;
        q.bootstrapAmount = p.bootstrapAmount;
        q.shareRecipient = p.shareRecipient;
    }

    function _copyEvent(MondaloreParimutuelMarketFactory.EventMarketParams calldata p)
        internal
        pure
        returns (MondaloreParimutuelMarketFactory.EventMarketParams memory q)
    {
        q.collateralToken = p.collateralToken;
        q.collateralDecimals = p.collateralDecimals;
        q.virtualReserve = p.virtualReserve;
        q.stakeEndTimestamp = p.stakeEndTimestamp;
        q.resolveAfterTimestamp = p.resolveAfterTimestamp;
        q.metadataHash = p.metadataHash;
        q.outcomeLabels = p.outcomeLabels;
        q.metadataURI = p.metadataURI;
        q.minBootstrapTotal = p.minBootstrapTotal;
        q.bootstrapAmount = p.bootstrapAmount;
        q.shareRecipient = p.shareRecipient;
    }
}

contracts/factory/MondaloreParimutuelDep.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "../token/MondaloreOutcomeToken.sol";
import "../core/MondaloreVParimutuelMarket.sol";

// ─── Price sub-deployer ───────────────────────────────────────────────────────

/// @title MondalorePriceMarketDeployer
/// @notice Deploys outcome tokens + PRICE market. Split from event deployer to stay under 24KB.
contract MondalorePriceMarketDeployer {
    address public immutable facade;
    address public immutable factory;

    error OnlyFacade();
    error EmptyLabel();

    modifier onlyFacade() {
        if (msg.sender != facade) revert OnlyFacade();
        _;
    }

    constructor(address facade_, address factory_) {
        facade  = facade_;
        factory = factory_;
    }

    function deployPriceMarket(
        address owner_,
        address feeRecipient_,
        address creator_,
        address collateralToken_,
        uint8 collateralDecimals_,
        uint8 numOutcomes_,
        uint256 virtualReserve_,
        uint256 stakeEndTimestamp_,
        uint256 resolveAfterTimestamp_,
        bytes32 metadataHash_,
        address chainlinkFeed_,
        uint256 priceThreshold_,
        MondaloreVParimutuelMarket.PriceThresholdKind priceKind_,
        uint256 priceUpperBound_,
        uint256 maxPriceStaleness_,
        uint256 minBootstrapTotal_,
        string[] calldata outcomeLabels
    ) external onlyFacade returns (address market, address[] memory tokens) {
        tokens = _deployOutcomeTokens(outcomeLabels, collateralDecimals_);
        MondaloreVParimutuelMarket mkt = new MondaloreVParimutuelMarket(
            factory,
            owner_,
            feeRecipient_,
            creator_,
            collateralToken_,
            collateralDecimals_,
            numOutcomes_,
            virtualReserve_,
            stakeEndTimestamp_,
            resolveAfterTimestamp_,
            MondaloreVParimutuelMarket.MarketKind.PRICE,
            metadataHash_,
            chainlinkFeed_,
            priceThreshold_,
            priceKind_,
            priceUpperBound_,
            maxPriceStaleness_,
            minBootstrapTotal_
        );
        market = address(mkt);
    }

    function _deployOutcomeTokens(string[] calldata labels, uint8 decimals_)
        internal
        returns (address[] memory tokens)
    {
        uint256 n = labels.length;
        tokens = new address[](n);
        for (uint256 i = 0; i < n; i++) {
            if (bytes(labels[i]).length == 0) revert EmptyLabel();
            tokens[i] = address(new MondaloreOutcomeToken(labels[i], "OUT", decimals_, factory));
        }
    }
}

// ─── Event sub-deployer ───────────────────────────────────────────────────────

/// @title MondaloreEventMarketDeployer
/// @notice Deploys outcome tokens + EVENT market. Split from price deployer to stay under 24KB.
contract MondaloreEventMarketDeployer {
    address public immutable facade;
    address public immutable factory;

    error OnlyFacade();
    error EmptyLabel();

    modifier onlyFacade() {
        if (msg.sender != facade) revert OnlyFacade();
        _;
    }

    constructor(address facade_, address factory_) {
        facade  = facade_;
        factory = factory_;
    }

    function deployEventMarket(
        address owner_,
        address feeRecipient_,
        address creator_,
        address collateralToken_,
        uint8 collateralDecimals_,
        uint8 numOutcomes_,
        uint256 virtualReserve_,
        uint256 stakeEndTimestamp_,
        uint256 resolveAfterTimestamp_,
        bytes32 metadataHash_,
        uint256 minBootstrapTotal_,
        string[] calldata outcomeLabels
    ) external onlyFacade returns (address market, address[] memory tokens) {
        tokens = _deployOutcomeTokens(outcomeLabels, collateralDecimals_);
        MondaloreVParimutuelMarket mkt = new MondaloreVParimutuelMarket(
            factory,
            owner_,
            feeRecipient_,
            creator_,
            collateralToken_,
            collateralDecimals_,
            numOutcomes_,
            virtualReserve_,
            stakeEndTimestamp_,
            resolveAfterTimestamp_,
            MondaloreVParimutuelMarket.MarketKind.EVENT,
            metadataHash_,
            address(0),
            0,
            MondaloreVParimutuelMarket.PriceThresholdKind.ABOVE,
            0,
            0,
            minBootstrapTotal_
        );
        market = address(mkt);
    }

    function _deployOutcomeTokens(string[] calldata labels, uint8 decimals_)
        internal
        returns (address[] memory tokens)
    {
        uint256 n = labels.length;
        tokens = new address[](n);
        for (uint256 i = 0; i < n; i++) {
            if (bytes(labels[i]).length == 0) revert EmptyLabel();
            tokens[i] = address(new MondaloreOutcomeToken(labels[i], "OUT", decimals_, factory));
        }
    }
}

// ─── Facade ───────────────────────────────────────────────────────────────────

/// @title MondaloreParimutuelDeployer
/// @notice Thin facade — factory calls this; it delegates to typed sub-deployers.
///         Deploying sub-deployers in the constructor keeps this contract small.
contract MondaloreParimutuelDeployer {
    address public immutable factory;
    MondalorePriceMarketDeployer public immutable priceDeployer;
    MondaloreEventMarketDeployer public immutable eventDeployer;

    error OnlyFactory();
    error ZeroAddress();
    error InvalidPriceDeployer();
    error InvalidEventDeployer();

    modifier onlyFactory() {
        if (msg.sender != factory) revert OnlyFactory();
        _;
    }

    /// @param factory_ Address of MondaloreParimutuelMarketFactory.
    /// @param priceDeployer_ Pre-deployed MondalorePriceMarketDeployer with facade == address(this) (use CREATE address prediction).
    /// @param eventDeployer_ Pre-deployed MondaloreEventMarketDeployer with facade == address(this).
    /// @dev Sub-deployers are deployed in separate txs so facade initcode stays under EIP-3860 limit.
    constructor(address factory_, address priceDeployer_, address eventDeployer_) {
        if (factory_ == address(0) || priceDeployer_ == address(0) || eventDeployer_ == address(0)) {
            revert ZeroAddress();
        }
        factory = factory_;
        MondalorePriceMarketDeployer p = MondalorePriceMarketDeployer(priceDeployer_);
        MondaloreEventMarketDeployer e = MondaloreEventMarketDeployer(eventDeployer_);
        if (p.facade() != address(this) || p.factory() != factory_) revert InvalidPriceDeployer();
        if (e.facade() != address(this) || e.factory() != factory_) revert InvalidEventDeployer();
        priceDeployer = p;
        eventDeployer = e;
    }

    function deployPriceMarket(
        address owner_,
        address feeRecipient_,
        address creator_,
        address collateralToken_,
        uint8 collateralDecimals_,
        uint8 numOutcomes_,
        uint256 virtualReserve_,
        uint256 stakeEndTimestamp_,
        uint256 resolveAfterTimestamp_,
        bytes32 metadataHash_,
        address chainlinkFeed_,
        uint256 priceThreshold_,
        MondaloreVParimutuelMarket.PriceThresholdKind priceKind_,
        uint256 priceUpperBound_,
        uint256 maxPriceStaleness_,
        uint256 minBootstrapTotal_,
        string[] calldata outcomeLabels
    ) external onlyFactory returns (address market, address[] memory tokens) {
        return priceDeployer.deployPriceMarket(
            owner_, feeRecipient_, creator_, collateralToken_, collateralDecimals_,
            numOutcomes_, virtualReserve_, stakeEndTimestamp_, resolveAfterTimestamp_,
            metadataHash_, chainlinkFeed_, priceThreshold_, priceKind_, priceUpperBound_,
            maxPriceStaleness_, minBootstrapTotal_, outcomeLabels
        );
    }

    function deployEventMarket(
        address owner_,
        address feeRecipient_,
        address creator_,
        address collateralToken_,
        uint8 collateralDecimals_,
        uint8 numOutcomes_,
        uint256 virtualReserve_,
        uint256 stakeEndTimestamp_,
        uint256 resolveAfterTimestamp_,
        bytes32 metadataHash_,
        uint256 minBootstrapTotal_,
        string[] calldata outcomeLabels
    ) external onlyFactory returns (address market, address[] memory tokens) {
        return eventDeployer.deployEventMarket(
            owner_, feeRecipient_, creator_, collateralToken_, collateralDecimals_,
            numOutcomes_, virtualReserve_, stakeEndTimestamp_, resolveAfterTimestamp_,
            metadataHash_, minBootstrapTotal_, outcomeLabels
        );
    }
}

contracts/factory/MondaloreParimutuelMar.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable2Step.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "../token/MondaloreOutcomeToken.sol";
import "../core/MondaloreVParimutuelMarket.sol";
import "./MondaloreParimutuelDeployer.sol";

interface IWETH {
    function deposit() external payable;
}

/// @title MondaloreParimutuelMarketFactory
/// @notice Core vPari factory (single-market creates). Batch deployment lives in MondaloreParimutuelBatchFactory.
contract MondaloreParimutuelMarketFactory is Ownable2Step {
    using SafeERC20 for IERC20;
    error InvalidAddress();
    error NotCreator();
    error InvalidCollateral();
    error InvalidConfig();
    error InvalidOutcomes();
    error InvalidFeed();
    error InvalidTime();
    error InvalidMeta();
    error InvalidBins();
    error InvalidDeployer();
    error InvalidBootstrap();
    error TooManyResolutionAdmins();
    error InvalidResolutionAdmin();

    uint256 public constant MAX_RESOLUTION_ADMINS = 10;
    uint256 public constant RESOLUTION_THRESHOLD = 3;

    mapping(address => bool) public isResolutionAdmin;
    address[] public resolutionAdmins;

    mapping(address => bool) public isSupportedCollateral;

    /// @notice Registered Chainlink (or mock) feed per asset key, e.g. keccak256(abi.encodePacked("BTC")).
    mapping(bytes32 => address) public priceFeeds;

    address public feeRecipient;
    address public optimisticOracleV2;
    /// @notice Default UMA bond token (WETH on Base / Base Sepolia). Used when EventMarketParams.umaRewardCurrency is address(0).
    address public umaBondCurrency;
    /// @notice Optional helper contract allowed to call create functions.
    address public batchExecutor;
    /// @notice Deploys token + market bytecode (set after deploy: deploy sub-deployers + MondaloreParimutuelDeployer(factory, priceDep, eventDep), then setMarketDeployer).
    address public marketDeployer;
    /// @notice Wrapped native token (MockWETH on Monad testnet). Native MON markets wrap bootstrap into this ERC20.
    address public wrappedNativeToken;

    address[] public markets;
    mapping(address => bool) public isMarket;
    mapping(address => address[]) private _marketOutcomeTokens;

    event SupportedCollateralAdded(address indexed token);
    event SupportedCollateralRemoved(address indexed token);
    event PriceFeedUpdated(bytes32 indexed assetKey, address feed);
    event FeeRecipientUpdated(address indexed recipient);
    event OptimisticOracleV2Updated(address indexed oracle);
    event UmaBondCurrencyUpdated(address indexed currency);
    event MarketDeployerUpdated(address indexed deployer);
    event WrappedNativeTokenUpdated(address indexed token);

    event MarketCreated(
        address indexed market,
        MondaloreVParimutuelMarket.MarketKind indexed kind,
        address indexed collateralToken,
        address[] outcomeTokens,
        string[] outcomeLabels,
        uint256 stakeEndTimestamp,
        uint256 resolveAfterTimestamp,
        bytes32 metadataHash,
        address creator
    );

    constructor(address owner_, address feeRecipient_, address optimisticOracleV2_, address umaBondCurrency_) Ownable(owner_) {
        if (feeRecipient_ == address(0)) revert InvalidAddress();
        feeRecipient = feeRecipient_;
        optimisticOracleV2 = optimisticOracleV2_;
        umaBondCurrency = umaBondCurrency_;
    }

    modifier onlyCreator() {
        if (msg.sender != owner() && msg.sender != batchExecutor) revert NotCreator();
        _;
    }

    function setFeeRecipient(address r) external onlyOwner {
        if (r == address(0)) revert InvalidAddress();
        feeRecipient = r;
        emit FeeRecipientUpdated(r);
    }

    function setOptimisticOracleV2(address oo) external onlyOwner {
        optimisticOracleV2 = oo;
        emit OptimisticOracleV2Updated(oo);
    }

    function setBatchExecutor(address executor) external onlyOwner {
        batchExecutor = executor;
    }

    function setMarketDeployer(address d) external onlyOwner {
        if (d == address(0)) revert InvalidAddress();
        marketDeployer = d;
        emit MarketDeployerUpdated(d);
    }

    function setWrappedNativeToken(address token) external onlyOwner {
        if (token == address(0)) revert InvalidAddress();
        wrappedNativeToken = token;
        emit WrappedNativeTokenUpdated(token);
    }

    function setUmaBondCurrency(address c) external onlyOwner {
        umaBondCurrency = c;
        emit UmaBondCurrencyUpdated(c);
    }

    /// @notice Set up to 10 wallets allowed to sign EVENT market resolutions (3-of-10 required on-chain).
    function setResolutionAdmins(address[] calldata admins) external onlyOwner {
        if (admins.length > MAX_RESOLUTION_ADMINS) revert TooManyResolutionAdmins();

        for (uint256 i = 0; i < resolutionAdmins.length; i++) {
            isResolutionAdmin[resolutionAdmins[i]] = false;
        }
        delete resolutionAdmins;

        for (uint256 i = 0; i < admins.length; i++) {
            address a = admins[i];
            if (a == address(0)) revert InvalidResolutionAdmin();
            for (uint256 j = 0; j < i; j++) {
                if (admins[j] == a) revert InvalidResolutionAdmin();
            }
            resolutionAdmins.push(a);
            isResolutionAdmin[a] = true;
        }
    }

    function resolutionThreshold() external pure returns (uint256) {
        return RESOLUTION_THRESHOLD;
    }

    function resolutionAdminsLength() external view returns (uint256) {
        return resolutionAdmins.length;
    }

    function addSupportedCollateral(address token) external onlyOwner {
        if (isSupportedCollateral[token]) revert InvalidConfig();
        isSupportedCollateral[token] = true;
        emit SupportedCollateralAdded(token);
    }

    function removeSupportedCollateral(address token) external onlyOwner {
        if (!isSupportedCollateral[token]) revert InvalidConfig();
        isSupportedCollateral[token] = false;
        emit SupportedCollateralRemoved(token);
    }

    /// @notice Register or disable a price feed for an asset key (e.g. keccak256(abi.encodePacked("BTC"))).
    /// @dev Pass feed = address(0) to disable market creation for that asset.
    function setPriceFeed(bytes32 assetKey, address feed) external onlyOwner {
        if (assetKey == bytes32(0)) revert InvalidFeed();
        priceFeeds[assetKey] = feed;
        emit PriceFeedUpdated(assetKey, feed);
    }

    /// @notice True if `token` is a registered outcome ERC20 for `market`.
    function isOutcomeTokenForMarket(address market, address token) external view returns (bool) {
        address[] storage arr = _marketOutcomeTokens[market];
        for (uint256 i = 0; i < arr.length; i++) {
            if (arr[i] == token) return true;
        }
        return false;
    }

    struct PriceMarketParams {
        address collateralToken;
        uint8 collateralDecimals;
        uint256 virtualReserve;
        uint256 stakeEndTimestamp;
        uint256 resolveAfterTimestamp;
        bytes32 metadataHash;
        string[] outcomeLabels;
        /// @notice UI / app metadata (e.g. `ipfs://...`), persisted for price markets too.
        string metadataURI;
        /// @notice Asset key, e.g. keccak256(abi.encodePacked("BTC")). Must be registered via setPriceFeed.
        bytes32 priceAssetKey;
        uint256 priceThreshold;
        MondaloreVParimutuelMarket.PriceThresholdKind priceKind;
        uint256 priceUpperBound;
        uint256 maxPriceStaleness;
        uint256[] priceBinLower;
        uint256[] priceBinUpper;
        /// @notice Minimum `totalAmount` for permissionless `bootstrapLiquidity` (0 = only >0 and divisible).
        uint256 minBootstrapTotal;
        /// @notice Bootstrap liquidity amount (must be >= minBootstrapTotal and divisible by numOutcomes).
        uint256 bootstrapAmount;
        /// @notice Recipient of bootstrap shares (typically msg.sender or a liquidity pool).
        address shareRecipient;
    }

    struct EventMarketParams {
        address collateralToken;
        uint8 collateralDecimals;
        uint256 virtualReserve;
        uint256 stakeEndTimestamp;
        uint256 resolveAfterTimestamp;
        bytes32 metadataHash;
        string[] outcomeLabels;
        /// @notice UI / app metadata (e.g. `ipfs://...`).
        string metadataURI;
        uint256 minBootstrapTotal;
        /// @notice Bootstrap liquidity amount (must be >= minBootstrapTotal and divisible by numOutcomes).
        uint256 bootstrapAmount;
        /// @notice Recipient of bootstrap shares (typically msg.sender or a liquidity pool).
        address shareRecipient;
    }

    function createPriceMarket(PriceMarketParams calldata p) external payable returns (address market) {
        market = _createPriceMarket(p, msg.sender);
    }

    function createEventMarket(EventMarketParams calldata p) external payable returns (address market) {
        market = _createEventMarket(p, msg.sender);
    }

    function getMarketOutcomeTokens(address market) external view returns (address[] memory) {
        return _marketOutcomeTokens[market];
    }

    /// @notice Total number of created markets.
    function marketsLength() external view returns (uint256) {
        return markets.length;
    }

    function _decimalsForCollateral(address token, uint8 templateDec) internal pure returns (uint8) {
        if (token == address(0)) return 18;
        return templateDec;
    }

    /// @dev `collateralToken == address(0)` means native MON when registered; market uses `wrappedNativeToken`.
    function _resolveCollateral(address collateralToken) internal view returns (address effective, bool isNativeInput) {
        if (collateralToken == address(0)) {
            if (wrappedNativeToken == address(0) || !isSupportedCollateral[address(0)]) revert InvalidCollateral();
            return (wrappedNativeToken, true);
        }
        if (!isSupportedCollateral[collateralToken]) revert InvalidCollateral();
        return (collateralToken, false);
    }

    function _createPriceMarket(PriceMarketParams calldata p, address creator) internal returns (address) {
        (address effectiveCollateral, bool isNativeInput) = _resolveCollateral(p.collateralToken);
        uint8 collateralDecimals = isNativeInput ? 18 : _decimalsForCollateral(p.collateralToken, p.collateralDecimals);
        if (p.outcomeLabels.length < 2 || p.outcomeLabels.length > 32) revert InvalidOutcomes();
        // Fix #8: explicit bounds check before uint8 cast (defensive — the >32 check above already
        // prevents truncation, but this makes the intent unambiguous).
        require(p.outcomeLabels.length <= type(uint8).max, "Labels overflow");
        if (p.priceAssetKey == bytes32(0)) revert InvalidFeed();
        address chainlinkFeed = priceFeeds[p.priceAssetKey];
        if (chainlinkFeed == address(0)) revert InvalidFeed();
        if (p.maxPriceStaleness == 0) revert InvalidConfig();
        if (p.stakeEndTimestamp <= block.timestamp || p.resolveAfterTimestamp <= p.stakeEndTimestamp) revert InvalidTime();
        if (p.metadataHash == bytes32(0)) revert InvalidMeta();

        if (p.priceBinLower.length > 0) {
            if (p.priceBinLower.length != p.outcomeLabels.length || p.priceBinUpper.length != p.outcomeLabels.length) {
                revert InvalidBins();
            }
        } else {
            if (p.outcomeLabels.length != 2) revert InvalidBins();
            if (p.priceKind == MondaloreVParimutuelMarket.PriceThresholdKind.IN_RANGE) {
                if (p.priceThreshold >= p.priceUpperBound) revert InvalidConfig();
            }
        }

        if (marketDeployer == address(0)) revert InvalidDeployer();
        (address market, address[] memory tokens) = MondaloreParimutuelDeployer(marketDeployer).deployPriceMarket(
            owner(),
            feeRecipient,
            creator,
            effectiveCollateral,
            collateralDecimals,
            uint8(p.outcomeLabels.length),
            p.virtualReserve,
            p.stakeEndTimestamp,
            p.resolveAfterTimestamp,
            p.metadataHash,
            chainlinkFeed,
            p.priceThreshold,
            p.priceKind,
            p.priceUpperBound,
            p.maxPriceStaleness,
            p.minBootstrapTotal,
            p.outcomeLabels
        );

        _wireMarket(market, tokens, p.metadataURI, p.priceBinLower, p.priceBinUpper);
        _seedMarket(market, effectiveCollateral, isNativeInput, p.bootstrapAmount, p.shareRecipient, uint8(p.outcomeLabels.length));
        _register(
            market,
            MondaloreVParimutuelMarket.MarketKind.PRICE,
            effectiveCollateral,
            tokens,
            p.outcomeLabels,
            p.stakeEndTimestamp,
            p.resolveAfterTimestamp,
            p.metadataHash,
            creator
        );
        return market;
    }

    function _createEventMarket(EventMarketParams calldata p, address creator) internal returns (address) {
        (address effectiveCollateral, bool isNativeInput) = _resolveCollateral(p.collateralToken);
        uint8 collateralDecimals = isNativeInput ? 18 : _decimalsForCollateral(p.collateralToken, p.collateralDecimals);
        if (p.outcomeLabels.length < 2 || p.outcomeLabels.length > 32) revert InvalidOutcomes();
        // Fix #8: explicit bounds check before uint8 cast.
        require(p.outcomeLabels.length <= type(uint8).max, "Labels overflow");
        if (resolutionAdmins.length < RESOLUTION_THRESHOLD) revert InvalidConfig();
        if (p.stakeEndTimestamp <= block.timestamp || p.resolveAfterTimestamp <= p.stakeEndTimestamp) revert InvalidTime();
        if (p.metadataHash == bytes32(0)) revert InvalidMeta();

        if (marketDeployer == address(0)) revert InvalidDeployer();
        (address market, address[] memory tokens) = MondaloreParimutuelDeployer(marketDeployer).deployEventMarket(
            owner(),
            feeRecipient,
            creator,
            effectiveCollateral,
            collateralDecimals,
            uint8(p.outcomeLabels.length),
            p.virtualReserve,
            p.stakeEndTimestamp,
            p.resolveAfterTimestamp,
            p.metadataHash,
            p.minBootstrapTotal,
            p.outcomeLabels
        );

        _wireMarket(market, tokens, p.metadataURI, _emptyBins(), _emptyBins());
        _seedMarket(market, effectiveCollateral, isNativeInput, p.bootstrapAmount, p.shareRecipient, uint8(p.outcomeLabels.length));
        _register(
            market,
            MondaloreVParimutuelMarket.MarketKind.EVENT,
            effectiveCollateral,
            tokens,
            p.outcomeLabels,
            p.stakeEndTimestamp,
            p.resolveAfterTimestamp,
            p.metadataHash,
            creator
        );
        return market;
    }

    function _emptyBins() internal pure returns (uint256[] memory z) {
        z = new uint256[](0);
    }

    /// @notice Pull bootstrap collateral from msg.sender and seed the market atomically.
    /// @dev Native MON (`isNativeInput`): caller sends `bootstrapAmount` as msg.value; factory wraps to WETH then seeds.
    ///      ERC20: caller must have pre-approved this factory for `bootstrapAmount`; msg.value must be 0.
    function _seedMarket(
        address market,
        address effectiveCollateral,
        bool isNativeInput,
        uint256 bootstrapAmount,
        address shareRecipient,
        uint8 numOutcomes
    ) internal {
        if (bootstrapAmount == 0) revert InvalidBootstrap();
        if (shareRecipient == address(0)) revert InvalidBootstrap();
        if (bootstrapAmount % uint256(numOutcomes) != 0) revert InvalidBootstrap();

        if (isNativeInput) {
            if (msg.value != bootstrapAmount) revert InvalidBootstrap();
            IWETH(wrappedNativeToken).deposit{value: bootstrapAmount}();
            IERC20(effectiveCollateral).forceApprove(market, bootstrapAmount);
            MondaloreVParimutuelMarket(payable(market)).bootstrapLiquidity(bootstrapAmount, shareRecipient);
        } else {
            if (msg.value != 0) revert InvalidBootstrap();
            IERC20(effectiveCollateral).safeTransferFrom(msg.sender, address(this), bootstrapAmount);
            IERC20(effectiveCollateral).forceApprove(market, bootstrapAmount);
            MondaloreVParimutuelMarket(payable(market)).bootstrapLiquidity(bootstrapAmount, shareRecipient);
        }
    }

    function _wireMarket(
        address market,
        address[] memory tokens,
        string memory metadataURI,
        uint256[] memory binLo,
        uint256[] memory binHi
    ) internal {
        for (uint256 i = 0; i < tokens.length; i++) {
            MondaloreOutcomeToken(tokens[i]).transferOwnership(market);
        }
        MondaloreVParimutuelMarket(payable(market)).initialize(tokens, binLo, binHi, metadataURI);
    }

    function _register(
        address market,
        MondaloreVParimutuelMarket.MarketKind kind,
        address collateral,
        address[] memory tokens,
        string[] memory labels,
        uint256 stakeEnd,
        uint256 resolveAfter,
        bytes32 meta,
        address creator
    ) internal {
        markets.push(market);
        isMarket[market] = true;
        for (uint256 i = 0; i < tokens.length; i++) {
            _marketOutcomeTokens[market].push(tokens[i]);
        }
        emit MarketCreated(market, kind, collateral, tokens, labels, stakeEnd, resolveAfter, meta, creator);
    }

}

